--- /dev/null
+++ b/test/monday.test.js
@@ -0,0 +1,45 @@
+const assert = require('assert');
+const Module = require('module');
+const path = require('path');
+
+const calls = [];
+const gotMock = () => {};
+gotMock.extend = (opts) => {
+  gotMock.opts = opts;
+  return async ({ json }) => {
+    calls.push(json);
+    const q = json.query;
+    let data;
+    if (q.includes('items_page_by_column_values'))
+      data = { items_page_by_column_values: { cursor: null, items: [{ id: '1', name: 'a', column_values: [{ id: 'c1', text: 'x' }] }] } };
+    else if (q.includes('next_items_page'))
+      data = { next_items_page: { cursor: null, items: [{ id: '3', name: 'c', column_values: [] }] } };
+    else if (q.includes('items_page'))
+      data = { boards: [{ items_page: { cursor: 'cur', items: [{ id: '2', name: 'b', column_values: [] }] } }] };
+    else data = { op0: { id: '9' } };
+    return { body: { data } };
+  };
+};
+const cfgPath = path.resolve(__dirname, '../src/config.js');
+const origLoad = Module._load;
+Module._load = function (req, parent, ...r) {
+  if (req === 'got') return gotMock;
+  if (parent && parent.filename.endsWith('monday.js') && req === '../config')
+    return { monday: { apiKey: 'k', bId: 5, cIds: { key: 'c1' } } };
+  return origLoad.call(this, req, parent, ...r);
+};
+const m = require('../src/api/monday');
+
+(async () => {
+  assert.strictEqual(gotMock.opts.headers['API-Version'], '2026-10');
+  const f = await m.find('key', 'x');
+  assert.strictEqual(f[0].key, 'x');
+  assert(!/items_by_column_values/.test(calls[0].query.replace('items_page_by_column_values', '')));
+  assert.deepStrictEqual(calls[0].variables.columns, [{ column_id: 'c1', column_values: ['x'] }]);
+  const all = await m.findAll();
+  assert.deepStrictEqual(all.map((i) => i.id), ['2', '3']);
+  assert(!/\bitems\s*\{[^}]*\}\s*\}\s*\}/.test('') );
+  await m.save({ id: '7', key: 'z' });
+  assert(calls[calls.length - 1].query.includes('$bId: ID!'));
+  console.log('ok');
+})().catch((e) => { console.error(e); process.exit(1); });

